    public function allocateCredits()
    {   // Get POST data
        $ledger_id = $this->input->post('ledger_id', true); // true for XSS filtering
        $credit_balance = $this->input->post('credit_balance', true);
        $master_id = $this->session->userdata('id');
        // echo '<pre>'; print_r($_POST); die;
        // Optional: Validate input (recommended)
        // Validate input correctly
        if (!isset($ledger_id) || !isset($credit_balance)) {
            echo "<script>alert('Ledger ID and Credit Balance are required.'); window.history.back();</script>";
            return;
        }


        // Example: You can call your insertOrUpdateCredit function here
        $result = $this->CoinModel->insertOrUpdateCredit($ledger_id, $credit_balance, $master_id,  1); // assuming master_id = 0 and credit_type = 1

        if ($result == 'updated') {
            echo "<script>alert('Credit updated successfully.'); window.location.href='" . base_url('ledger') . "';</script>";
        } else {
            echo "<script>alert('Credit allocated successfully.'); window.location.href='" . base_url('ledger') . "';</script>";
        }
    }

    // View Allocation Page
    public function allocateCoins()
    {
        $role = $this->session->userdata('role'); // Fetch role from session

        if ($role === 'Super Admin') {
            $data['users'] = $this->CoinModel->getMasters(); // Get Masters for Super Admin
        } elseif ($role === 'Master') {
            $data['users'] = $this->CoinModel->getStaff(); // Get Staff for Master
        } else {
            show_error('Unauthorized access.', 403);
        }
        // Load the database library if not already loaded
        $this->load->database();

        $this->db->select('ct.id, ct.amount, ct.type, ct.created_at, ct.sender_id, ct.receiver_id, 
                   sender_ledger.ledger_name AS sender_name, 
                   receiver_ledger.ledger_name AS receiver_name');
        $this->db->from('coin_transactions ct');
        $this->db->join('tbl_ledger sender_ledger', 'ct.sender_id = sender_ledger.id', 'left');
        $this->db->join('tbl_ledger receiver_ledger', 'ct.receiver_id = receiver_ledger.id', 'left');

        $this->db->where('ct.shift_id', NULL); // Ensure only NULL shift_id records

        $this->db->group_start(); // Start grouping conditions
        $this->db->where('ct.sender_id', $this->session->userdata('id'));

        // if ($this->session->userdata['role'] == 'Master') {
        //     $this->db->or_where('ct.receiver_id', $this->session->userdata('id'));
        // }
        $this->db->group_end(); // End grouping conditions

        $this->db->order_by('ct.id', 'desc');

        $query = $this->db->get();

        // Fetch the results as an array
        $data['transactions'] = $query->result_array();

        // Example: Printing the result
        //echo '<pre>';print_r($transactions); die;
        //$this->load->view('coin/allocate_coins', $data);
        $data['_view'] = 'coin/allocate_coins';
        $this->load->view('layouts/main', $data);
    }

