    public function processAllocationMaster()
    {
        $receiver_id = $this->input->post('receiver_id', true);
        $master_id = $this->session->userdata('id');
        $amount = (int) $this->input->post('amount', true);
        $transaction_type = $this->input->post('transactiontype', true);
        $remarks = trim($this->input->post('remarks', true)) ?: 'Cash transaction';

        if (empty($receiver_id) || empty($amount) || empty($transaction_type) || $amount <= 0) {
            echo "<script>alert('All fields are required and amount must be positive.'); window.history.back();</script>";
            return;
        }

        $coin_data = [
            'amount' => $amount,
            'status' => 1,
            'created_at' => date('Y-m-d H:i:s')
        ];
        $total_received = $this->db->select_sum('amount')
            ->from('coin_transactions')
            ->where('receiver_id', $master_id)
            ->where('deposite_byto_master', 0)
            ->get()->row()->amount ?? 0;

        $total_allocated = $this->db->select_sum('amount')
            ->from('coin_transactions')
            ->where('sender_id', $master_id)
            ->where('deposite_byto_master', 1)
            ->get()->row()->amount ?? 0;
        //echo $total_received. '  '.$total_allocated; die; 
        $master_balance = (int)$total_received - (int)$total_allocated;
        if ($transaction_type == 'D') {
            // Step 1: Calculate master's available balance


            if ($master_balance < $amount) {
                echo "<script>alert('Insufficient master balance to allocate this amount.'); window.history.back();</script>";
                return;
            }

            // Deposit: admin → client
            $coin_data['type'] = 'allocation';
            $coin_data['sender_id'] = $master_id;
            $coin_data['receiver_id'] = $receiver_id;
            $coin_data['deposite_byto_master'] = 1;

            // Update ledger: Set coin_balance to given amount
            $this->db->set('coin_balance', $amount);
            $this->db->where('id', $receiver_id);
            $this->db->update('tbl_ledger');
        } elseif ($transaction_type == 'W') {
            // 1. Validate client has enough balance
            //$ledgercoinbal = (int) $this->CoinModel->get_coin_balance($receiver_id);
            $ledgercoinbal = get_client_coin_balance($receiver_id);
            //echo $ledgercoinbal; die;
            if ($ledgercoinbal < $amount) {
                echo "<script>alert('Client has insufficient balance.'); window.history.back();</script>";
                return;
            }
            // Withdraw: client → admin
            $coin_data['type'] = 'spend';
            $coin_data['sender_id'] = $receiver_id;
            $coin_data['receiver_id'] = $master_id;
            $coin_data['deposite_byto_master'] = 1;
            // Optional: Master must also be allowed to receive (have balance capacity)

            // Check current balance first
            $ledger = $this->db->get_where('tbl_ledger', ['id' => $receiver_id])->row();
            $ledgercoinbal = $this->CoinModel->get_coin_balance($receiver_id);
            // echo $ledger->coin_balance .' '. $amount; die; 
            if ($ledger && $ledgercoinbal >= $amount) {
                // Deduct amount from receiver's balance
                $this->db->set('coin_balance', 'coin_balance - ' . $amount, false);
                $this->db->where('id', $receiver_id);
                $this->db->update('tbl_ledger');
                // 2. Add amount to master's balance
                $this->db->set('coin_balance', "coin_balance + {$amount}", false)
                    ->where('id', $master_id)
                    ->update('tbl_ledger');
            } else {
                echo "<script>alert('Insufficient balance for withdrawal.'); window.history.back();</script>";
                return;
            }
        } else {
            echo "<script>alert('Invalid transaction type.'); window.history.back();</script>";
            return;
        }

        $insert = $this->db->insert('coin_transactions', $coin_data);

        if ($insert) {
            echo "<script>alert('Transaction successful.'); window.location.href='" . base_url('ledger') . "';</script>";
        } else {
            echo "<script>alert('Transaction failed. Please try again.'); window.history.back();</script>";
        }
    }

    // Process Allocation
    public function processAllocation()
    {
        $receiver_id = $this->input->post('receiver_id');
        $amount = $this->input->post('amount');
        $sender_id = $this->session->userdata('id');
        $role = $this->session->userdata('role');
        $transactiontype = $this->input->post('transactiontype');
        if ($transactiontype == 'W') {
            $receiver_id = $this->session->userdata('id');
            $sender_id = $this->input->post('receiver_id');
        }
        // echo $transactiontype.' '.$receiver_id.' '.$sender_id; die;
        log_message('error', $transactiontype . ' ' . $receiver_id . ' ' . $sender_id);

        if ($role === 'Super Admin' || $role === 'Master') {
            if ($this->CoinModel->allocateCoins($sender_id, $receiver_id, $amount)) {
                if ($transactiontype == 'W') {
                    $this->session->set_flashdata('success', 'Coins withdraw successfully.');
                } else {
                    $this->session->set_flashdata('success', 'Coins allocated successfully.');
                }
            } else {
                $this->session->set_flashdata('error', 'Insufficient balance.');
            }
        } else {
            show_error('Unauthorized access.', 403);
        }
        //$this->session->set_flashdata('success', 'Coins allocated successfully!');
        //return true;
        redirect('ledger');
    }

